css='''*{box-sizing:border-box}body{margin:0;background:#110d1b;color:#f1e6ff;font:16px/1.55 system-ui,sans-serif}main{max-width:1260px;margin:auto;padding:30px 22px}h1{font-size:32px;line-height:1.15}h2{margin-top:48px}p{max-width:920px}a{color:#caaaef}button{background:#31243e;color:#ede2ff;border:1px solid #ad8bce77;border-radius:24px;padding:9px 16px;cursor:pointer}button.active{color:#d7ffa0;border-color:#d7ffa0}nav{display:flex;gap:9px;flex-wrap:wrap;margin:20px 0}.note{background:#261d36;border:1px solid #8e76ad55;padding:16px 20px;border-radius:20px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:22px}.card{background:#20182c;border:1px solid #ac8fcd44;border-radius:22px;padding:16px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.solo{max-width:280px;margin:auto}.shot{display:block;position:relative;line-height:0}.shot img{display:block;width:100%;border-radius:12px}.edge{position:absolute;left:0;right:0;border-top:2px dashed #b6ed7888;pointer-events:none}.caption{font-size:13px;color:#cdbee0;margin:8px 0}.status{color:#d4ff9f}.tag{font-size:12px;letter-spacing:.04em;color:#bbaecc}details{margin:10px 0}summary{cursor:pointer}.card[hidden]{display:none}.report{display:flex;gap:14px;flex-wrap:wrap}footer{margin:36px 0;color:#c7b4dc;font-size:13px}'''
parts=[f'<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HeyPals — keyboard243</title><style>{css}</style></head><body><main><h1>Поля над клавиатурой — проверка 243</h1><p>Общий обработчик оставляет поле и подтверждение в видимой части экрана. Материал 93%, размытие 8px, зелёные действия и светлая кнопка Back сохранены.</p><div class="note"><b>Разные виды доказательств.</b> Браузерные снимки ниже моделируют доступную высоту при клавиатуре: сама клавиатура не нарисована. Пунктир отмечает её верхнюю границу. Настоящий WKWebView Simulator проверен отдельно с фокусом, однако вызвать настоящую программную клавиатуру не удалось. Эти снимки не подтверждают поведение физического iPhone или AirPlay.</div><p class="report"><span>Пульт: <b class="status">32/32</b></span><span>Native host: <b class="status">24/24</b></span><span>Ошибки JS: <b class="status">0</b></span><a href="browser-before/report.json">Baseline: 17 нарушений границы</a><a href="browser-after/report.json">Отчёт пульта</a><a href="host-after/report.json">Отчёт хоста</a></p><nav id="filters"><button class="active" data-filter="all">Все 56 состояний</button><button data-filter="393">393px</button><button data-filter="320">320px</button><button data-filter="webkit">WebKit</button><button data-filter="chromium">Chrome</button><button data-filter="overlay">Клавиатура поверх layout</button><button data-filter="resize">Layout уменьшается</button></nav><h2>Пульт: до / после</h2><p>Настоящий маршрут /play с controller-bridge.js и tabs.js. Комнаты — явно заданные QA-данные; подключение по интернету не имитируется.</p><section class="cards">']
lookup={(r['engine'],r['width'],r['mode'],r['name']):r for r in before['rows']}
