 frac=row['bottom']/row['innerHeight']*100
 return f'<a href="{folder}/{row["file"]}" class="shot"><img loading="lazy" src="{folder}/{row["file"]}" alt="{labels[row["name"]]}"><span class="edge" style="top:{frac:.4f}%"></span></a>'
